package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.hq.app.setting.PolicyDate;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, in the order
 * they were added, and the sheet's claimed-total and due-total.
 *
 * Only OPEN, PENDING and SETTLED claims count, and a held person's OPEN and PENDING claims do not. A claim's figure is its settled due, else the figure a statement
 * bound it to (never while PENDING), else its live due at the person's grade's rate in force on its date, at least the sheet's floor
 * (n/a without a rate), plus the late charge of an overdue OPEN or PENDING claim (see {@link LatePct}), each rounded by the
 * claim's rounding (see {@link PolicyDate}).
 * A person's due-total adds up their counting claims' figures, skipping n/a; it is n/a when the grade
 * in force on the sheet's today has no rate there and no counting claim has a figure. The sheet's due-total
 * adds up the people's due-totals, skipping n/a.
 */
@Service
public class Rollup {

    static final String NA = "n/a";

    /** One person's figures, as text with two decimals (due-total may be n/a). */
    public record Figures(String name, String claimed, String dueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }

    /** The sheet's figures at one moment: people by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
        boolean sameTotals(Snapshot other) {
            return claimedTotal.equals(other.claimedTotal) && dueTotal.equals(other.dueTotal);
        }
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetClock clock;
    private final Floor floor;
    private final LatePct latePct;
    private final PolicyDate policyDate;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetClock clock, Floor floor,
            LatePct latePct, PolicyDate policyDate) {
        this.policyDate = policyDate;
        this.floor = floor;
        this.latePct = latePct;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.clock = clock;
    }

    public Snapshot take(String sheetId) {
        LocalDate today = clock.today(sheetId);
        List<Rate> sheetRates = rates.findBySheet(sheetId);
        List<Claim> sheetClaims = claims.findBySheet(sheetId);
        BigDecimal least = floor.of(sheetId);
        LatePct.Charge late = latePct.of(sheetId);
        PolicyDate.Policy policy = policyDate.of(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheet(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean figured = false;
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!person.counts(claim.getStatus())) continue;
                claimed = claimed.add(claim.getAmount());
                RoundingMode mode = policy.modeFor(claim);
                BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least, mode), mode);
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                }
            }
            boolean na = Rate.inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !figured;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) dueTotal = dueTotal.add(due);
            figures.put(person.getId(), new Figures(person.getName(), text(claimed), na ? NA : text(due)));
        }
        return new Snapshot(figures, text(claimedTotal), text(dueTotal));
    }

    /** The due-total of the sheet's counting claims dated from {@code from} to {@code to}, both included:
     *  each claim's figure at its person's grade, skipping n/a. */
    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheet(sheetId);
        List<Claim> sheetClaims = claims.findBySheet(sheetId);
        BigDecimal least = floor.of(sheetId);
        LatePct.Charge late = latePct.of(sheetId);
        PolicyDate.Policy policy = policyDate.of(sheetId);
        BigDecimal sum = zero();
        for (Person person : people.findBySheet(sheetId)) {
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!person.counts(claim.getStatus())) continue;
                if (claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) continue;
                RoundingMode mode = policy.modeFor(claim);
                BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least, mode), mode);
                if (figure != null) sum = sum.add(figure);
            }
        }
        return sum.setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The ROLLUP lines for each person whose figures moved since {@code before} (a new person counts
     *  as moved), then a TOTALS line when the sheet's totals moved. */
    public List<String> changes(String sheetId, String user, Snapshot before, Snapshot after) {
        String prefix = " sheet=" + sheetId + " by=" + user;
        List<String> lines = new ArrayList<>();
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                lines.add("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + now.dueTotal());
            }
        });
        if (!after.sameTotals(before)) {
            lines.add("TOTALS" + prefix + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
        return lines;
    }

    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least, RoundingMode mode) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
                .orElse(null), least);
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return Objects.requireNonNull(value).setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Notes the sheet's figures before the change writes anything, for {@link AuditRollup} to compare. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<Rollup.Snapshot> before) {
        before.set(rollup.take(sheetId));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Floor;
import net.officefloor.hq.app.setting.LatePct;
import net.officefloor.hq.app.setting.PolicyDate;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
 * their claims that counts (OPEN, PENDING or SETTLED) to the figure it has now (a PENDING claim's live one), unbinds the rest
 * (leaving a held person's OPEN claims, which count in no total, as they are), and moves
 * the person's statement count, last due-total and date (the sheet's today) on.
 *
 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
 * the rate of the person's grade in force on its date (the grade in force on that date too), at least the sheet's floor (n/a without a rate). The due-total adds up the counting
 * claims' figures, each with its late charge on top (see {@link LatePct}; the bound figure leaves it out, so it
 * keeps following the sheet's today), skipping n/a; it is n/a when the grade in force on today has no rate there and no counting claim
 * has a figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
            SheetClock clock, Floor floor, LatePct latePct, PolicyDate policyDate, Out<Statement> statementOut) {
        String sheetId = person.getSheetId();
        LocalDate today = clock.today(sheetId);
        List<Rate> rates = rateRepository.findBySheet(sheetId);
        BigDecimal least = floor.of(sheetId);
        LatePct.Charge late = latePct.of(sheetId);
        PolicyDate.Policy policy = policyDate.of(sheetId);
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
            boolean counts = claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED;
            if (counts && !person.counts(claim.getStatus())) {
                continue;           // a held person's OPEN or PENDING claim: in no total, and left as it is
            } else if (!counts) {
                claim.setStated(false);
                claim.setStatedDue(null);
            } else {
                RoundingMode mode = policy.modeFor(claim);
                BigDecimal figure = figure(claim, person, rates, least, mode);
                if (figure != null) figured = true;
                BigDecimal due = late.addTo(claim, figure, mode);
                if (due != null) sum = sum.add(due);
                claim.setStated(true);
                claim.setStatedDue(figure);
                counted++;
            }
            claims.save(claim);
        }
        BigDecimal dueTotal = Rate.inForce(rates, person.gradeOn(today), today).isEmpty() && !figured ? null : sum;
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statementOut.set(new Statement(dueTotal, counted));
    }

    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor, unless already fixed; null when n/a. */
    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least, RoundingMode mode) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
                .orElse(null), least);
    }
}

